import csv, json, sys, argparse
from decimal import Decimal, ROUND_HALF_UP

def convert(amount, currency, rates):
    if not currency:
        currency = "USD"
    rate = rates.get(currency, 1.0)
    return amount / rate

def main():
    ap = argparse.ArgumentParser(); ap.add_argument("input"); ap.add_argument("-o", required=True)
    a = ap.parse_args()
    rates = json.load(open("rates.json"))
    totals = {}
    n = 0
    skipped = 0
    for row in csv.DictReader(open(a.input)):
        raw = row["amount"].strip()
        if not raw:
            skipped += 1
            continue
        try:
            amt = float(raw)
        except ValueError:
            skipped += 1
            continue
        usd = convert(amt, row["currency"].strip() if row["currency"] else "", rates)
        merchant = row["merchant"].strip().lower()
        totals[merchant] = totals.get(merchant, 0.0) + usd
        n += 1
    out = {
        "totals_usd": {
            k: float(Decimal(str(v)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
            for k, v in totals.items()
        },
        "skipped": skipped,
        "rows": n
    }
    json.dump(out, open(a.o, "w"))

if __name__ == "__main__":
    main()
ENDOFSCRIPT'"}

